"""Restore IP Addresses — place three dots, validating each octet.

An octet is 1-3 digits, at most 255, and may not have a leading zero.

Time: O(1) — at most 3^4 splits   Space: O(1)
"""
from typing import List


class Solution:
    def restoreIpAddresses(self, s: str) -> List[str]:
        out, parts = [], []

        def walk(start: int) -> None:
            if len(parts) == 4:
                if start == len(s):
                    out.append(".".join(parts))
                return
            for size in range(1, 4):
                if start + size > len(s):
                    break
                piece = s[start:start + size]
                if (piece[0] == "0" and size > 1) or int(piece) > 255:
                    continue
                parts.append(piece)
                walk(start + size)
                parts.pop()

        walk(0)
        return out
